/* Palette: #fefae0 (bg), #d4a373 (pet), #faedcd (card), #6b705c (text), #a5a58d (accent) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background-color: #fefae0;
  color: #6b705c;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-board {
  background-color: #faedcd;
  border-radius: 24px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(107, 112, 92, 0.15);
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #6b705c;
  letter-spacing: 1px;
}

/* Pet drawing */
.pet-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 140px;
}

.pet {
  position: relative;
  width: 100px;
  height: 120px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.pet-head {
  width: 80px;
  height: 70px;
  background-color: #d4a373;
  border-radius: 40px 40px 30px 30px;
  position: relative;
  border: 3px solid #6b705c;
}

.pet-eye {
  width: 12px;
  height: 12px;
  background-color: #6b705c;
  border-radius: 50%;
  position: absolute;
  top: 24px;
}

.pet-eye.left {
  left: 16px;
}

.pet-eye.right {
  right: 16px;
}

.pet-mouth {
  width: 24px;
  height: 12px;
  border-bottom: 3px solid #6b705c;
  border-radius: 0 0 12px 12px;
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
}

.pet-body {
  width: 90px;
  height: 50px;
  background-color: #d4a373;
  border-radius: 20px 20px 40px 40px;
  border: 3px solid #6b705c;
  margin-top: -6px;
  z-index: -1;
}

/* Mood text */
.mood {
  font-size: 1.125rem;
  font-weight: 600;
  min-height: 1.5em;
  color: #6b705c;
}

/* Stats */
.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.stat {
  text-align: left;
}

.stat label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
  font-size: 1rem;
}

.bar-container {
  width: 100%;
  height: 20px;
  background-color: #e9e5d8;
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid #a5a58d;
}

.bar-fill {
  height: 100%;
  width: 0%;
  background-color: #a5a58d;
  border-radius: 8px;
  transition: width 0.3s ease, background-color 0.3s ease;
}

/* Controls */
.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  background-color: #a5a58d;
  color: #fefae0;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 100px;
}

button:hover {
  background-color: #8a8a72;
}

button:focus-visible {
  outline: 3px solid #6b705c;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background-color: #6b705c;
}

/* Responsive tweaks */
@media (max-width: 400px) {
  .game-board {
    padding: 24px 16px;
    gap: 20px;
  }
  h1 {
    font-size: 1.5rem;
  }
  button {
    padding: 10px 16px;
    min-width: 80px;
  }
}

// Pixel Virtual Pet logic
const state = {
  hunger: 80,
  happiness: 80,
  energy: 80
};

const hungerFill = document.getElementById('hunger-fill');
const happinessFill = document.getElementById('happiness-fill');
const energyFill = document.getElementById('energy-fill');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodText = document.getElementById('mood-text');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  // Update bar widths
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';

  // Update ARIA values
  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.setAttribute('aria-valuenow', state.energy);

  // Update bar colors based on value
  const colorForValue = (v) => {
    if (v < 30) return '#e07a5f';
    if (v < 60) return '#f2cc8f';
    return '#a5a58d';
  };
  hungerFill.style.backgroundColor = colorForValue(state.hunger);
  happinessFill.style.backgroundColor = colorForValue(state.happiness);
  energyFill.style.backgroundColor = colorForValue(state.energy);

  // Update mood text
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 80) mood = 'Your pet is feeling fantastic!';
  else if (avg >= 60) mood = 'Your pet is happy and content.';
  else if (avg >= 40) mood = 'Your pet could use some attention.';
  else if (avg >= 20) mood = 'Your pet is feeling neglected...';
  else mood = 'Your pet is very sad and needs care!';
  moodText.textContent = mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

// Attach event listeners
document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

// Initialize UI
updateUI();
